export function mountAutomationEditor({svg,track,key,def,bars,checkpoint,changed,onValues}){
 let selected=null,drag=null,from=0,to=bars,snap=true;const ns='http://www.w3.org/2000/svg',points=()=>track.automation.curves[key]||[],clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 const tools=document.createElement('div');tools.className='curve-toolbar';tools.innerHTML='<button type="button" data-curve-action="in">＋ Zoom</button><button type="button" data-curve-action="out">− Zoom</button><button type="button" data-curve-action="all">Tout afficher</button><button type="button" data-curve-action="snap" aria-pressed="true">Grille 1/16</button><span>Glisser : déplacer · clic : ajouter · clic droit / Suppr : effacer</span>';svg.before(tools);svg.setAttribute('tabindex','0');svg.style.touchAction='none';
 function paint(){const list=points().slice().sort((a,b)=>a.bar-b.bar),x=p=>(p.bar-from)/(to-from)*800,y=p=>180-(p.value-def.min)/(def.max-def.min)*180;svg.replaceChildren();
  for(let i=0;i<=8;i++){const line=document.createElementNS(ns,'path');line.setAttribute('d',`M${i*100} 0V180`);line.setAttribute('class','curve-grid');svg.append(line);const label=document.createElementNS(ns,'text');label.setAttribute('x',i*100+4);label.setAttribute('y','15');label.textContent=(from+(to-from)*i/8+1).toFixed(to-from<8?2:0);svg.append(label);}
  const all=[{bar:from,value:valueAt(list,from,def.value)},...list.filter(p=>p.bar>=from&&p.bar<=to),{bar:to,value:valueAt(list,to,def.value)}],poly=document.createElementNS(ns,'polyline');poly.setAttribute('points',all.map(p=>`${x(p)},${y(p)}`).join(' '));svg.append(poly);
  for(const p of list)if(p.bar>=from&&p.bar<=to){const c=document.createElementNS(ns,'circle');c.setAttribute('cx',x(p));c.setAttribute('cy',y(p));c.setAttribute('r',p===selected?'7':'6');c.setAttribute('data-curve-point',points().indexOf(p));c.setAttribute('class',p===selected?'selected':'');svg.append(c);}
 }
 function position(e){const r=svg.getBoundingClientRect(),bar=clamp(from+(e.clientX-r.left)/r.width*(to-from),from,to),value=clamp(def.max-(e.clientY-r.top)/r.height*(def.max-def.min),def.min,def.max);return {bar:snap&&!e.altKey?Math.round(bar*16)/16:Math.round(bar*960)/960,value};}
 const commit=()=>{const list=points().sort((a,b)=>a.bar-b.bar);track.automation.curves[key]=list.filter((p,i)=>!i||p.bar-list[i-1].bar>=1/1920);if(track.automation.mode==='off')track.automation.mode='read';const mode=document.getElementById('automationMode');if(mode)mode.value=track.automation.mode;changed();paint();};
 svg.onpointerdown=e=>{if(e.button!==0)return;svg.focus();const hit=e.target.closest('[data-curve-point]');checkpoint();if(!hit){selected=position(e);track.automation.curves[key]??=[];track.automation.curves[key].push(selected);}else selected=points()[Number(hit.dataset.curvePoint)];drag={x:e.clientX,y:e.clientY,point:selected,bar:selected.bar,value:selected.value};svg.setPointerCapture(e.pointerId);onValues?.(selected);paint();e.preventDefault();};
 svg.onpointermove=e=>{if(!drag)return;let p=position(e);if(e.shiftKey){const r=svg.getBoundingClientRect();p={bar:clamp(drag.bar+(e.clientX-drag.x)/r.width*(to-from)*.1,from,to),value:clamp(drag.value-(e.clientY-drag.y)/r.height*(def.max-def.min)*.1,def.min,def.max)};}Object.assign(drag.point,p);onValues?.(drag.point);paint();};svg.onpointerup=()=>{if(drag){drag=null;commit();}};svg.onpointercancel=()=>{if(drag){drag=null;commit();}};
 svg.ondblclick=e=>e.preventDefault();
 const remove=()=>{if(!selected)return;checkpoint();track.automation.curves[key]=points().filter(p=>p!==selected);selected=null;commit();};svg.oncontextmenu=e=>{e.preventDefault();const hit=e.target.closest('[data-curve-point]');if(hit)selected=points()[Number(hit.dataset.curvePoint)];remove();};svg.onkeydown=e=>{if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();remove();}else if(selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();checkpoint();if(e.key==='ArrowLeft'||e.key==='ArrowRight')selected.bar=clamp(selected.bar+(e.key==='ArrowRight'?1:-1)*(e.altKey?1/960:1/16),0,bars);else selected.value=clamp(selected.value+(e.key==='ArrowUp'?1:-1)*(def.max-def.min)/(e.shiftKey?1000:100),def.min,def.max);onValues?.(selected);commit();}};
 tools.onclick=e=>{const b=e.target.closest('[data-curve-action]');if(!b)return;const a=b.dataset.curveAction;if(a==='snap'){snap=!snap;b.setAttribute('aria-pressed',snap);return;}if(a==='all'){from=0;to=bars;}else{const center=selected?.bar??(from+to)/2,width=clamp((to-from)*(a==='in'?.5:2),.25,bars);from=clamp(center-width/2,0,bars-width);to=from+width;}paint();};paint();
 return {redraw:paint};
}
function valueAt(points,at,fallback){if(!points.length)return fallback;if(at<=points[0].bar)return points[0].value;for(let i=1;i<points.length;i++)if(at<=points[i].bar){const a=points[i-1],b=points[i];return a.value+(b.value-a.value)*(at-a.bar)/(b.bar-a.bar);}return points.at(-1).value;}
